insert into public.cars (id, make, model, gen, year, country, cc, tier, hp, nm, acc, top, kg, value, blurb, pools, tastes, photo_url, photo_credit) values
  ('ferrari-f40', 'Ferrari', 'F40', '', 1987, 'Italy', 'IT', 'Legendary', 478, 577, 4.2, 324, 1100, 412000, 'Built for Ferrari’s 40th anniversary and the last car Enzo Ferrari signed off personally. Twin-turbo V8, no power steering, no ABS.', array['apex']::text[], array['supercars']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/F40_Ferrari_20090509.jpg?width=800', 'Will ainsworth · CC BY-SA 3.0 · Wikimedia Commons'),
  ('mclaren-f1', 'McLaren', 'F1', '', 1992, 'United Kingdom', 'GB', 'Legendary', 627, 651, 3.2, 386, 1138, 980000, 'Central driving seat flanked by two passengers. Held the production car top-speed record for over a decade.', array['apex']::text[], array['supercars']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/1996%20McLaren%20F1%20Chassis%20No%2063%206.1%20Front.jpg?width=800', 'Chelsea Jay · CC BY-SA 4.0 · Wikimedia Commons'),
  ('porsche-911-rs27', 'Porsche', '911 Carrera RS 2.7', 'F-series', 1973, 'Germany', 'DE', 'Legendary', 210, 255, 5.8, 245, 975, 268000, 'A homologation special with thinner steel, lighter glass and the ducktail spoiler that became a 911 signature.', array['heritage']::text[], array['classics']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Porsche%20911%20Carrera%20RS%2C%20Bj.%201972-73%20(2016-07-02%2001%20Sp).JPG?width=800', 'Lothar Spurzem · CC BY-SA 2.0 de · Wikimedia Commons'),
  ('toyota-2000gt', 'Toyota', '2000GT', 'MF10', 1967, 'Japan', 'JP', 'Legendary', 150, 175, 8.6, 220, 1120, 305000, 'Japan’s first serious grand tourer. Around 350 were built, with a Yamaha-developed straight-six.', array['heritage']::text[], array['classics', 'jdm']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/TOYOTA_2000GT.jpg?width=800', 'Unknown author · CC BY-SA 3.0 · Wikimedia Commons'),
  ('mercedes-300sl', 'Mercedes-Benz', '300 SL Gullwing', 'W198', 1954, 'Germany', 'DE', 'Legendary', 215, 275, 8.8, 260, 1295, 498000, 'Direct fuel injection and a spaceframe chassis so tall at the sills that the doors had to open upward.', array['heritage']::text[], array['classics']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Mercedes-Benz%20W198%20300%20SL%20Gullwing%20Genf%202019%201Y7A5009.jpg?width=800', 'Alexander Migl · CC BY-SA 4.0 · Wikimedia Commons'),
  ('porsche-959', 'Porsche', '959', '', 1986, 'Germany', 'DE', 'Legendary', 450, 500, 3.7, 317, 1450, 512000, 'Group B technology for the road: sequential twin turbos, adjustable ride height and computer-controlled all-wheel drive.', array['apex']::text[], array['supercars']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Porsche_959_%E2%80%93_Frontansicht_(2)%2C_21._M%C3%A4rz_2013%2C_D%C3%BCsseldorf.jpg?width=800', 'M 93 · CC BY-SA 3.0 de · Wikimedia Commons'),
  ('nissan-skyline-r34', 'Nissan', 'Skyline GT-R V-Spec', 'R34', 1999, 'Japan', 'JP', 'Epic', 280, 392, 4.9, 250, 1560, 142000, 'RB26 twin-turbo straight-six and ATTESA all-wheel drive. Officially rated at 280 hp under Japan’s gentlemen’s agreement.', array['apex']::text[], array['jdm']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/2001%20Nissan%20Skyline%20GT-R%20V-Spec%20II%20R34.jpg?width=800', 'MrWalkr · CC BY-SA 4.0 · Wikimedia Commons'),
  ('honda-nsx-na1', 'Honda', 'NSX', 'NA1', 1990, 'Japan', 'JP', 'Epic', 274, 285, 5.7, 270, 1365, 96000, 'An aluminium monocoque mid-engine car tuned with input from Formula 1 drivers, proving a supercar could be used daily.', array['apex']::text[], array['jdm', 'supercars']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/AcuraNSX-05-cropped.jpg?width=800', 'Travis Rigel Lukas Hornung · CC BY 2.0 · Wikimedia Commons'),
  ('lamborghini-countach', 'Lamborghini', 'Countach LP400', '', 1974, 'Italy', 'IT', 'Epic', 375, 368, 5.6, 290, 1065, 188000, 'Scissor doors and a wedge profile by Marcello Gandini. The early LP400 is the cleanest form, before the wings arrived.', array['heritage', 'apex']::text[], array['supercars', 'classics']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Lamborghini_Countach_-_Flickr_-_exfordy_(2)_(cropped-2).jpg?width=800', 'Brian Snelson from Hockley, Essex, England · CC BY 2.0 · Wikimedia Commons'),
  ('toyota-supra-a80', 'Toyota', 'Supra RZ', 'A80', 1993, 'Japan', 'JP', 'Epic', 330, 431, 4.6, 250, 1490, 88000, 'The 2JZ-GTE engine is known for handling far more boost than it left the factory with.', array['apex']::text[], array['jdm']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Tuned%20Toyota%20Supra%20(A80)%20front.JPG?width=800', 'Tokumeigakarinoaoshima · CC0 · Wikimedia Commons'),
  ('lancia-delta-evo', 'Lancia', 'Delta HF Integrale Evo', '', 1991, 'Italy', 'IT', 'Epic', 210, 300, 5.7, 220, 1340, 109000, 'Six consecutive World Rally Championship titles for Lancia. The Evo added wider arches and an adjustable rear spoiler.', array['apex']::text[], array['rally']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Lancia%20Delta%20HF%20Integrale%20Evo%205.jpg?width=800', 'Calreyn88 · CC BY-SA 4.0 · Wikimedia Commons'),
  ('mercedes-c111', 'Mercedes-Benz', 'C111-II', '', 1970, 'Germany', 'DE', 'Epic', 350, 392, 4.8, 300, 1240, 160000, 'A four-rotor Wankel test bed in a glassfibre wedge. Mercedes famously refused the blank cheques offered to build it.', array['heritage']::text[], array['concepts']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Mercedes-Benz_Museum_C111_200901241511.jpg?width=800', 'Bergfalke2 · CC BY-SA 3.0 · Wikimedia Commons'),
  ('lancia-stratos', 'Lancia', 'Stratos HF Stradale', '', 1973, 'Italy', 'IT', 'Epic', 190, 226, 6.8, 230, 980, 205000, 'Built around a Ferrari Dino V6 purely to win rallies. It took three straight World Rally Championship titles.', array['heritage']::text[], array['rally', 'classics']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Lancia%20Stratos%20HF%20001.JPG?width=800', 'Tennen-Gas · CC BY-SA 3.0 · Wikimedia Commons'),
  ('jaguar-etype-s1', 'Jaguar', 'E-Type 3.8', 'Series 1', 1961, 'United Kingdom', 'GB', 'Epic', 265, 353, 7, 241, 1234, 175000, 'Launched at the 1961 Geneva show with a claimed 150 mph, disc brakes all round and a price far below its rivals.', array['heritage']::text[], array['classics']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Jaguar%20E-Type%20Series%201%203.8%20Litre%201961.jpg?width=800', 'DeFacto · CC BY-SA 4.0 · Wikimedia Commons'),
  ('bmw-30-csl', 'BMW', '3.0 CSL', 'E9', 1972, 'Germany', 'DE', 'Rare', 200, 277, 7.3, 220, 1165, 68000, 'A lightweight homologation coupé with aluminium panels. Its racing aero kit earned it the nickname Batmobile.', array['heritage']::text[], array['classics']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/BMWE9CSc.jpg?width=800', 'Olli1800 · CC BY-SA 3.0 · Wikimedia Commons'),
  ('mazda-rx7-fd', 'Mazda', 'RX-7', 'FD', 1992, 'Japan', 'JP', 'Rare', 255, 294, 5.3, 250, 1250, 54000, 'A sequential twin-turbo rotary in a low, light body. Near 50:50 weight distribution.', array['street', 'apex']::text[], array['jdm']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Mazda-rx7-1st-generation01.jpg?width=800', 'Taisyo · CC BY-SA 3.0 · Wikimedia Commons'),
  ('bmw-m3-e30', 'BMW', 'M3', 'E30', 1986, 'Germany', 'DE', 'Rare', 195, 230, 6.7, 235, 1200, 71000, 'Developed to go touring-car racing, and went on to become one of the most successful touring cars ever.', array['street', 'apex']::text[], array['everyday']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/BMW%20M3%20(E30)%20of%20Peter%20Brock%20at%20the%202025%20Adelaide%20Grand%20Final.jpg?width=800', 'Yu Chu Chin · CC BY-SA 4.0 · Wikimedia Commons'),
  ('alfa-giulia-gta', 'Alfa Romeo', 'Giulia Sprint GTA', 'Tipo 105', 1965, 'Italy', 'IT', 'Rare', 115, 142, 9.5, 185, 745, 62000, 'GTA stands for Gran Turismo Alleggerita: aluminium body panels over a lightened Giulia coupé.', array['heritage']::text[], array['classics']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/1965%20Alfa%20Romeo%20Giulia%20Sprint%20GTA%20Red.jpg?width=800', 'MrWalkr · CC BY-SA 4.0 · Wikimedia Commons'),
  ('datsun-240z', 'Datsun', '240Z', 'S30', 1969, 'Japan', 'JP', 'Rare', 151, 198, 8, 200, 1044, 44500, 'A straight-six sports car priced against British roadsters. It became the best-selling sports car of its decade.', array['heritage']::text[], array['classics', 'jdm']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/1972%20Datsun%20240Z%20S30.jpg?width=800', 'MrWalkr · CC BY-SA 4.0 · Wikimedia Commons'),
  ('ford-sierra-cosworth', 'Ford', 'Sierra RS Cosworth', '', 1986, 'United Kingdom', 'GB', 'Rare', 204, 276, 6.2, 241, 1220, 41000, 'A Cosworth-developed turbo four and a whale-tail wing, built so Ford could go Group A touring-car racing.', array['street']::text[], array['everyday', 'rally']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Cosworth800px.jpg?width=800', 'Lemmus · Public domain · Wikimedia Commons'),
  ('ford-escort-cosworth', 'Ford', 'Escort RS Cosworth', 'Mk5', 1992, 'United Kingdom', 'GB', 'Rare', 227, 304, 6.2, 232, 1275, 52000, 'Sierra Cosworth running gear under an Escort body, with a rear wing that made real downforce at road speeds.', array['street']::text[], array['rally']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Is%20this%20a%20genuine%20Cosworth%3F%20(8644064293).jpg?width=800', 'Riley from Christchurch, New Zealand · CC BY 2.0 · Wikimedia Commons'),
  ('lancia-stratos-zero', 'Lancia', 'Stratos HF Zero', '', 1970, 'Italy', 'IT', 'Rare', 115, 140, 9, 200, 800, 58000, 'A Bertone show car only 84 cm tall, entered through the hinged windscreen. It led directly to the rally Stratos.', array['heritage']::text[], array['concepts']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Lancia_Stratos_Zero_(7522598642).jpg?width=800', 'Dustin May from Detroit, MI · CC BY-SA 2.0 · Wikimedia Commons'),
  ('vw-golf-gti-mk1', 'Volkswagen', 'Golf GTI', 'Mk1', 1976, 'Germany', 'DE', 'Common', 110, 140, 9, 182, 810, 14000, 'Fuel injection in a small hatchback. The car that started the hot-hatch category.', array['street', 'heritage']::text[], array['everyday']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/1982%20Volkswagen%20Golf%20GTi%20(Mk1)%20(14072934454).jpg?width=800', 'Riley from Christchurch, New Zealand · CC BY 2.0 · Wikimedia Commons'),
  ('peugeot-205-gti', 'Peugeot', '205 GTI 1.9', '', 1986, 'France', 'FR', 'Common', 130, 161, 7.8, 206, 875, 12500, 'Light, short and lively at the limit. The 1.9 added torque to the 1.6’s balance.', array['street']::text[], array['everyday']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Peugeot_205_front_20080121.jpg?width=800', 'Rudolf Stricker · CC BY-SA 3.0 · Wikimedia Commons'),
  ('mini-cooper-s', 'Mini', 'Cooper S', 'Mk1', 1964, 'United Kingdom', 'GB', 'Common', 76, 108, 10.9, 160, 650, 9800, 'Front-wheel drive with a transverse engine. Won the Monte Carlo Rally outright in 1964.', array['street', 'heritage']::text[], array['everyday', 'rally', 'classics']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/1965%20Austin%20Mini%20Cooper%20S%201275.jpg?width=800', 'initialdave · CC BY 2.0 · Wikimedia Commons'),
  ('renault-clio-williams', 'Renault', 'Clio Williams', '', 1993, 'France', 'FR', 'Common', 150, 175, 7.8, 215, 990, 9400, 'A 2.0 litre homologation special named after Renault’s Formula 1 engine partnership.', array['street']::text[], array['everyday']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Renault%20Clio%20Williams%202023.jpg?width=800', 'SunflowerYuri · CC BY-SA 4.0 · Wikimedia Commons'),
  ('toyota-ae86', 'Toyota', 'Sprinter Trueno', 'AE86', 1983, 'Japan', 'JP', 'Common', 130, 149, 8.5, 200, 940, 13200, 'Rear-wheel drive, a revvy 4A-GE twin-cam and pop-up lights. Mountain-pass drifters made it famous.', array['street']::text[], array['everyday', 'jdm']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/New%20stock%20ae86%20coupe.jpg?width=800', 'Jeff lange at English Wikipedia · Public domain · Wikimedia Commons'),
  ('honda-civic-ek9', 'Honda', 'Civic Type R', 'EK9', 1997, 'Japan', 'JP', 'Common', 185, 160, 6.7, 225, 1050, 16000, 'A hand-ported 1.6 litre VTEC making 185 hp, seam-welded shell and a helical limited-slip differential.', array['street']::text[], array['everyday', 'jdm']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Civic%20R%20EK9%201.JPG?width=800', 'Kenneth Britishracer · CC BY-SA 3.0 · Wikimedia Commons'),
  ('ford-fiesta-xr2', 'Ford', 'Fiesta XR2', 'Mk1', 1981, 'Germany', 'DE', 'Common', 84, 128, 10.5, 165, 790, 7000, 'Ford’s answer to the Golf GTI, with a 1.6 litre engine, sport seats and black trim. It made the hot hatch affordable.', array['street']::text[], array['everyday']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/1983%20Ford%20Fiesta%20XR2%20BS%20O24.jpg?width=800', 'MrWalkr · CC BY-SA 4.0 · Wikimedia Commons'),
  ('renault-5-gt-turbo', 'Renault', '5 GT Turbo', '', 1985, 'France', 'FR', 'Common', 115, 163, 7.9, 195, 830, 11000, 'A turbocharged supermini with a lot of lag and a lot of grin. It was quick enough in a straight line to embarrass bigger cars.', array['street']::text[], array['everyday']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Renault%205%20GT%20Turbo%2C%2014.%20ADAC%20Stormarn%20Retro%2C%20Zarpen%20(TR257116).jpg?width=800', 'Matti Blume · CC BY-SA 4.0 · Wikimedia Commons'),
  ('fiat-uno-turbo', 'Fiat', 'Uno Turbo i.e.', '', 1985, 'Italy', 'IT', 'Common', 105, 147, 8.3, 200, 845, 9000, 'A boxy Giugiaro hatchback with a turbo and fuel injection. In 1985 it was one of the fastest cars of its size.', array['street']::text[], array['everyday']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/1986%20Fiat%20Uno%20Turbo%20i.e%20(25420774522).jpg?width=800', 'Riley from Christchurch, New Zealand · CC BY 2.0 · Wikimedia Commons'),
  ('mazda-mx5-na', 'Mazda', 'MX-5', 'NA', 1989, 'Japan', 'JP', 'Common', 115, 136, 9, 188, 940, 13500, 'Pop-up lights, rear-wheel drive and a manual box. It revived the cheap roadster and went on to become the best-selling two-seat sports car ever.', array['street']::text[], array['everyday', 'jdm']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Mazda%20MX-5%20NA%20971.jpg?width=800', 'User StepInTheMirror on en.wikipedia · Public domain · Wikimedia Commons'),
  ('toyota-mr2-aw11', 'Toyota', 'MR2', 'AW11', 1984, 'Japan', 'JP', 'Common', 128, 149, 8, 200, 950, 15000, 'A small mid-engine coupé with a rev-happy twin-cam four. Few cars at this price have such an engine behind the driver.', array['street']::text[], array['everyday', 'jdm']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Toyota%20MR2%20AW11%20white.jpg?width=800', 'Jacob Frey 4A · CC BY 2.0 · Wikimedia Commons'),
  ('peugeot-106-rallye', 'Peugeot', '106 Rallye', '', 1993, 'France', 'FR', 'Common', 100, 108, 9.2, 190, 800, 8500, 'Stripped out, light and steel-wheeled. Built to homologate a one-make rally cup and still a favourite on cheap club events.', array['street']::text[], array['everyday', 'rally']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/1995%20Peugeot%20106%20Rallye%202.jpg?width=800', 'Calreyn88 · CC BY-SA 4.0 · Wikimedia Commons'),
  ('honda-integra-dc2', 'Honda', 'Integra Type R', 'DC2', 1995, 'Japan', 'JP', 'Rare', 197, 181, 6.7, 230, 1060, 52000, 'A hand-ported VTEC engine that screams to 8,400 rpm and a limited-slip differential. Often called the best front-wheel-drive car ever built.', array['street']::text[], array['jdm']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Honda%20Integra%20TYPE%20R%20(DC2%20%26%20DB8).jpg?width=800', 'Tokumeigakarinoaoshima · CC BY-SA 3.0 · Wikimedia Commons'),
  ('renault-5-turbo', 'Renault', '5 Turbo', '', 1980, 'France', 'FR', 'Rare', 160, 210, 6.9, 200, 970, 68000, 'A supermini turned into a rear-drive, mid-engine rally homologation special with huge flared arches.', array['street', 'heritage']::text[], array['rally', 'classics']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Nationale%20oldtimerdag%20Zandvoort%202010%2C%201981%20RENAULT%205%20TURBO%2C%20JH-VZ-86%20pic2.JPG?width=800', 'Alf van Beem · CC0 · Wikimedia Commons'),
  ('lotus-elise-s1', 'Lotus', 'Elise', 'S1', 1996, 'United Kingdom', 'GB', 'Rare', 118, 165, 5.8, 190, 725, 38000, 'A bonded aluminium tub weighing just 68 kg. It is quick because it is light, not because it is powerful.', array['street']::text[], array['everyday']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Lotus%20Elise%20S1%2C%20Pau%202015.jpg?width=800', 'Handelsgeselschaft · CC BY-SA 4.0 · Wikimedia Commons'),
  ('nissan-silvia-s15', 'Nissan', 'Silvia Spec-R', 'S15', 1999, 'Japan', 'JP', 'Rare', 247, 275, 6.1, 250, 1240, 47000, 'The last Silvia, with a turbocharged SR20DET and a six-speed gearbox. A drift-scene staple.', array['street']::text[], array['jdm']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Nissan_Silvia_S15_001.JPG?width=800', 'Tennen-Gas · CC BY-SA 3.0 · Wikimedia Commons'),
  ('porsche-944-turbo', 'Porsche', '944 Turbo', '', 1985, 'Germany', 'DE', 'Rare', 220, 330, 6.3, 245, 1280, 45000, 'A front-engine, transaxle Porsche with near-perfect weight balance. The Turbo made it a proper performance car.', array['street']::text[], array['classics', 'everyday']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/1986_944_Turbo.jpg?width=800', 'Daniel J. Leivick · CC BY-SA 3.0 · Wikimedia Commons'),
  ('bmw-2002-turbo', 'BMW', '2002 turbo', '', 1973, 'Germany', 'DE', 'Rare', 170, 240, 6.9, 211, 1035, 58000, 'Europe’s first turbocharged production saloon, launched just as the oil crisis hit. The mirror-image “turbo” lettering on the front spoiler made it infamous.', array['heritage']::text[], array['classics']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/BMW%202002%20Turbo%20(2008-06-28)%20ret.jpg?width=800', 'Spurzem - Lothar Spurzem · CC BY-SA 2.0 de · Wikimedia Commons'),
  ('lancia-fulvia-hf', 'Lancia', 'Fulvia Coupé HF', '1.6', 1969, 'Italy', 'IT', 'Rare', 115, 142, 9.5, 180, 925, 49000, 'A narrow-angle V4 and front-wheel drive. It won the 1972 International Championship for Manufacturers.', array['heritage']::text[], array['rally', 'classics']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/2006%20SAG%20-%20Lancia%20Fulvia%20Coup%C3%A9%20I%201967-01.JPG?width=800', 'Semnoz · CC BY-SA 3.0 · Wikimedia Commons'),
  ('toyota-celica-st205', 'Toyota', 'Celica GT-Four', 'ST205', 1994, 'Japan', 'JP', 'Rare', 255, 304, 5.9, 245, 1470, 41000, 'The road-going version of Toyota’s mid-90s World Rally Championship car, with all-wheel drive and a turbocharged 3S-GTE.', array['street']::text[], array['rally', 'jdm']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Toyota%20Celica%20GT-Four%20ST205%20(WRC)%20at%20the%202025%20Shannons%20Adelaide%20Rally%20(028A4653).jpg?width=800', 'Yu Chu Chin · CC BY 4.0 · Wikimedia Commons'),
  ('alpine-a110-1600s', 'Alpine', 'A110 1600S', '', 1971, 'France', 'FR', 'Rare', 138, 148, 6.5, 210, 720, 72000, 'A fibreglass body, a rear-mounted Renault engine and a famously agile chassis. It won the first World Rally Championship in 1973.', array['heritage']::text[], array['rally', 'classics']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Renault_Alpine_A_110_(Sp).JPG?width=800', 'Lothar Spurzem · CC BY-SA 2.0 de · Wikimedia Commons'),
  ('mitsubishi-evo-vi', 'Mitsubishi', 'Lancer Evolution VI', 'TME', 1999, 'Japan', 'JP', 'Epic', 276, 373, 4.6, 250, 1360, 96000, 'The Tommi Mäkinen Edition celebrated four straight WRC drivers’ titles, with a quicker-spooling turbo and a red-and-white Ralliart look.', array['street', 'apex']::text[], array['jdm', 'rally']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/2000%20Mitsubishi%20Lancer%20Evolution%20VI%20TME%20Rear.jpg?width=800', 'MrWalkr · CC BY-SA 4.0 · Wikimedia Commons'),
  ('subaru-impreza-22b', 'Subaru', 'Impreza 22B STi', 'GC8', 1998, 'Japan', 'JP', 'Epic', 276, 363, 5, 248, 1270, 168000, 'A 400-car run built to mark Subaru’s third WRC manufacturers’ title, with wide fenders copied from the rally car.', array['street', 'apex']::text[], array['jdm', 'rally']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/1998%20Subaru%20Impreza%2022B%20STi%20Rear.jpg?width=800', 'MrWalkr · CC BY-SA 4.0 · Wikimedia Commons'),
  ('porsche-930-turbo', 'Porsche', '911 Turbo 3.0', '930', 1975, 'Germany', 'DE', 'Epic', 260, 343, 5.5, 250, 1195, 135000, 'The first turbocharged 911, with a whale-tail spoiler and wide arches. The big lag is part of the legend.', array['heritage']::text[], array['classics', 'supercars']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Porsche%20930%20coupes%20IMG%205451.jpg?width=800', 'Alexander Migl · CC BY-SA 4.0 · Wikimedia Commons'),
  ('ferrari-308-gtb', 'Ferrari', '308 GTB', '', 1975, 'Italy', 'IT', 'Epic', 255, 289, 6.4, 250, 1090, 128000, 'A Pininfarina wedge with a mid-mounted V8. Early cars were made from fibreglass.', array['heritage']::text[], array['supercars', 'classics']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Ferrari%20308GTB%20Lightweight%20(1976)%20-%2014453314104%20(cropped).jpg?width=800', 'Original: Steve Glover from Bolton, Lancs., England / Deriva · CC BY 2.0 · Wikimedia Commons'),
  ('aston-martin-db5', 'Aston Martin', 'DB5', '', 1963, 'United Kingdom', 'GB', 'Epic', 282, 390, 7.1, 233, 1502, 165000, 'A 4.0 litre straight-six in an aluminium Superleggera body. Its role in Goldfinger made it the most famous car in cinema.', array['heritage']::text[], array['classics']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Aston_Martin_DB5_(Skyfall).jpg?width=800', 'DeFacto · CC BY-SA 4.0 · Wikimedia Commons'),
  ('bmw-m1', 'BMW', 'M1', 'E26', 1978, 'Germany', 'DE', 'Epic', 277, 330, 5.5, 262, 1300, 195000, 'BMW’s only mid-engine production car, designed by Giugetto Giugiaro and built partly by Lamborghini. It starred in its own one-make race series.', array['heritage', 'apex']::text[], array['supercars', 'classics']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/1979%20BMW%20M1%20Procar.jpg?width=800', 'Calreyn88 · CC BY-SA 4.0 · Wikimedia Commons'),
  ('audi-quattro', 'Audi', 'Quattro', '', 1980, 'Germany', 'DE', 'Epic', 200, 285, 7.1, 220, 1290, 92000, 'A turbocharged five-cylinder with permanent four-wheel drive. It changed rallying for good.', array['street']::text[], array['rally', 'classics']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Audi%20Quattro%20vl%20black.jpg?width=800', 'Unknown author · CC BY-SA 3.0 · Wikimedia Commons'),
  ('nissan-skyline-r32', 'Nissan', 'Skyline GT-R', 'R32', 1989, 'Japan', 'JP', 'Epic', 276, 358, 5.2, 250, 1430, 98000, 'The car that revived the GT-R name. Twin turbos and ATTESA all-wheel drive made it nearly unbeatable in Group A racing.', array['street', 'apex']::text[], array['jdm']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Nissan%20Skyline%20R32%20GT-R%20001.jpg?width=800', 'Tennen-Gas · CC BY-SA 3.0 · Wikimedia Commons'),
  ('lamborghini-miura', 'Lamborghini', 'Miura P400 S', '', 1968, 'Italy', 'IT', 'Legendary', 370, 369, 5.5, 280, 1293, 620000, 'The first mid-engine V12 road car. Marcello Gandini’s body had eyelash grilles around the headlights and started the supercar template.', array['heritage', 'apex']::text[], array['supercars', 'classics']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Lamborghini%20Miura%20P400%20S%20Classic-Days%202022%20DSC%200086.jpg?width=800', 'Alexander Migl · CC BY-SA 4.0 · Wikimedia Commons'),
  ('ferrari-250-gto', 'Ferrari', '250 GTO', '', 1962, 'Italy', 'IT', 'Legendary', 296, 294, 6.1, 280, 880, 1500000, 'Only 36 were built. It is the most valuable car in the world on the auction block, and it also won races.', array['heritage']::text[], array['classics', 'supercars']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/1962%20Ferrari%20250%20GTO%20SP25.jpg?width=800', 'MrWalkr · CC BY-SA 4.0 · Wikimedia Commons'),
  ('jaguar-xj220', 'Jaguar', 'XJ220', '', 1992, 'United Kingdom', 'GB', 'Legendary', 542, 644, 3.6, 341, 1470, 410000, 'Shown as a V12 all-wheel-drive concept and built as a twin-turbo V6. It was the fastest production car in the world for two years.', array['apex']::text[], array['supercars', 'concepts']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/JaguarXJ220.jpg?width=800', 'Brian Snelson · CC BY 2.0 · Wikimedia Commons'),
  ('bugatti-eb110', 'Bugatti', 'EB110 GT', '', 1991, 'Italy', 'IT', 'Legendary', 553, 611, 3.6, 342, 1620, 505000, 'A quad-turbo V12, all-wheel drive and a carbon-fibre chassis, launched on the 110th anniversary of Ettore Bugatti’s birth.', array['apex']::text[], array['supercars']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/1993%20Bugatti%20EB110%20GT%20in%20Grigio%20Scuro%2C%20front%20left%20(Miller).jpg?width=800', 'Mr.choppers · CC BY-SA 4.0 · Wikimedia Commons'),
  ('ferrari-enzo', 'Ferrari', 'Enzo', '', 2002, 'Italy', 'IT', 'Legendary', 651, 657, 3.4, 350, 1255, 780000, 'A Formula 1-derived carbon-fibre chassis and a 6.0 litre V12. Only 400 were built, and all were sold to selected customers.', array['apex']::text[], array['supercars']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Orange%20Enzo%20Ferrari%20(7191948164).jpg?width=800', 'Axion23 · CC BY 2.0 · Wikimedia Commons'),
  ('lexus-lfa', 'Lexus', 'LFA', '', 2010, 'Japan', 'JP', 'Legendary', 553, 480, 3.7, 325, 1480, 590000, 'A 4.8 litre V10 that revs from idle to redline in 0.6 seconds, so fast the analogue rev counter could not keep up.', array['apex']::text[], array['jdm', 'supercars']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Lexus_LFA_001.JPG?width=800', 'Tennen-Gas · CC BY-SA 3.0 · Wikimedia Commons'),
  ('porsche-carrera-gt', 'Porsche', 'Carrera GT', '', 2003, 'Germany', 'DE', 'Legendary', 603, 607, 3.5, 330, 1380, 560000, 'A V10 that began as an abandoned Le Mans engine, with a carbon-fibre monocoque and a ceramic clutch. It has no electronic stability control.', array['apex']::text[], array['supercars']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Porsche_Carrera_GT_-_Goodwood_Breakfast_Club_(July_2008).jpg?width=800', 'Brian Snelson from Hockley, Essex, England · CC BY 2.0 · Wikimedia Commons')
